        ReadinessChecks: {
            /**
             * @example ok
             * @enum {string}
             */
            database: "ok" | "unavailable";
            /**
             * @example ok
             * @enum {string}
             */
            redis: "ok" | "unavailable";
            /**
             * @example ok
             * @enum {string}
             */
            storage: "ok" | "unavailable";
        };
        UserCreate: {
            /** Format: email */
            email: string;
            /** Format: password */
            password: string;
        };
        UserRead: {
            id: number;
            /** Format: email */
            email: string;
            is_active: boolean;
        };
