        UserRoleUpdate: {
            is_admin: boolean;
        };
        PasswordChangeRequest: {
            /** Format: password */
            current_password: string;
            /** Format: password */
            new_password: string;
        };
        Token: {
            access_token: string;
            /** @default bearer */
            token_type: string;
            expiresIn: number;
        };
        /**
         * @description standard: importe uniquement ms_task et ms_task_link.
         *     full: reserve a une phase ulterieure (ressources/affectations).
         * @enum {string}
         */
        ImportMode: "standard" | "full";
        /** @enum {string} */
        BatchStatus: "pending" | "running" | "success" | "failed";
